CREATE OR REPLACE FUNCTION public.steps_ground_refusal(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare f record;
begin
  select * into f from steps_fit(p_world, p_x, p_y);
  if f.slope < steps_least() or f.slope > steps_most() then
    return 'Steps are laid on a slope of ' || metres(steps_least()) || ' m to ' || metres(steps_most())
      || ' m. This one is ' || metres(f.slope) || ' m.';
  end if;
  if f.twist > steps_twist() then
    return 'The two corners at each end of a flight have to be within ' || metres(steps_twist())
      || ' m of each other. These are ' || metres(f.twist) || ' m apart.';
  end if;
  return null;
end $function$
